import React, { Component } from "react";
import "./Signup.css";
import FormJson from "./formid";
import PagesJson from "./PagesJson";

export default class Signup extends Component {
    render() {
        const signData = FormJson.find(item => item.formId === 3);
        const leftsideContent = signData.content.find(section => section.leftside).leftside ;
        const rightsideContent = signData.content.find(section => section.rightside).rightside;
        const pagesdata=PagesJson.find(item => item.pageId === 4);
        const buttonsdata=pagesdata.buttons; 


        return (
            <div className="content-container">
                <div className="formbox">
                    <div className="button-box">
                        <div id="btn"></div>
                        {leftsideContent.map((item) =>(
                        <>
                        <input 
                        type={item.type} 
                        className={item.className} 
                        placeholder={item.placeholder} 
                        required />
                        </>
                        ))}
                        <button type="button" className="toggle-btn">{button1Text}</button>
                        <button type="button" className="toggle-btn">{button2Text}</button> 
                    </div>
                    <div className="social-icons">
                        <img src={pagesdata.Img2}/>
                        <img src={pagesdata.Img1} />
                    </div>

                    <form className="input-group">
                     <div className="input-left">
                        {leftsideContent.map((item) =>(
                       <>
                    <input 
                    type={item.type} 
                    className={item.className} 
                    placeholder={item.placeholder} 
                    required />
                    </>
                     ))}
                        </div>

                    <div className="input-right">
                    {rightsideContent.map((item) =>(
                       <>
                    <input 
                    type={item.type} 
                    className={item.className} 
                    placeholder={item.placeholder} 
                    required />
                    </>
                     ))}
                        </div>

                    </form>
                    <button type="submit" className="submit-btn">{button1Text}</button>

                </div>
            </div>
        );
    }
}
